import { Inject, Injectable } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { Observable, ReplaySubject } from 'rxjs';
import { distinctUntilChanged, filter, first, map } from 'rxjs/operators';
import { UntilDestroy, untilDestroyed } from '@ngneat/until-destroy';
import mixpanel from 'mixpanel-browser';

import {
  ANALYTICS_EVENT_MAP,
  ANALYTICS_TRACKER_ID,
  AnalyticsEvent,
  AnalyticsEventOptions,
} from './analytics.definitions';

declare global {
  interface Window {
    dataLayer: any[];
    gtag: (...args: any[]) => void;
  }
}

@UntilDestroy()
@Injectable()
export class AnalyticsService {
  private initialized: ReplaySubject<boolean> = new ReplaySubject(1);

  private serviceInitialized: boolean = false;

  constructor(
    @Inject(ANALYTICS_TRACKER_ID) private trackerId: string,
    private router: Router,
  ) {}

  public initialize(): void {
    if (this.serviceInitialized) {
      return;
    }

    this.injectScript();
    this.serviceInitialized = true;
  }

  private injectScript(): void {
    const script = document.createElement('script');
    script.async = true;
    script.src = `https://www.googletagmanager.com/gtag/js?id=${this.trackerId}`;
    script.onload = () => {
      this.initializeTracking();
    };
    document.head.appendChild(script);
    mixpanel.init('5bf95fe0b1082a95beb70c07ff6fa70e', {debug: true, track_pageview: true, persistence: 'localStorage'});
  }

  private initializeTracking(): void {
    window.dataLayer = window.dataLayer || [];
    window.gtag = function () {
      window.dataLayer.push(arguments);
    };
    window.gtag('js', new Date());
    window.gtag('config', this.trackerId);
    this.initialized.next(true);

    this.initializePageTracking();
  }

  private initializePageTracking(): void {
    this.router.events
      .pipe(
        filter((event) => event instanceof NavigationEnd),
        map((event: NavigationEnd) => event.urlAfterRedirects.split('?')[0]),
        distinctUntilChanged(),
        untilDestroyed(this),
      )
      .subscribe((url) => this.sendPageView(url));
  }

  public onInitialized(): Observable<boolean> {
    return this.initialized.pipe(first());
  }

  public sendEvent(event: AnalyticsEvent | AnalyticsEventOptions): void {
    console.log(this.getGaClientId());
    const api_secret = 'ZbThkMYCSyewJRz6TW2eSw';
    const eventOptions = typeof event === 'object' ? event : ANALYTICS_EVENT_MAP[event];
    console.log(eventOptions);
    fetch(`https://www.google-analytics.com/mp/collect?measurement_id=${this.trackerId}&api_secret=${api_secret}`, {
      method: 'POST',
      body: JSON.stringify({
        client_id: this.getGaClientId(),
        events: [{
          name: 'tutorial_begin',
          params: {},
        }],
      }),
    }).then(res => console.log('res: ', res));
    window.gtag('event', eventOptions.action, {
      event_category: eventOptions.category,
      event_label: eventOptions.label,
      value: eventOptions.value,
    });
  }

  private getGaClientId() {
    const cookie = {};
    document.cookie.split(';').forEach(function (el) {
      const splitCookie = el.split('=');
      const key = splitCookie[0].trim();
      const value = splitCookie[1];
      cookie[key] = value;
    });
    // @ts-ignore
    return cookie._ga.substring(6);
  }

  private sendPageView(url: string): void {
    const api_secret = 'ZbThkMYCSyewJRz6TW2eSw';
    fetch(`https://www.google-analytics.com/mp/collect?measurement_id=${this.trackerId}&api_secret=${api_secret}`, {
      method: 'POST',
      body: JSON.stringify({
        client_id: this.getGaClientId(),
        events: [
          {
            name: 'page_view',
            params: {
              page_location: url,
              engagement_time_msec: 1,
            },
          },
        ],
      }),
    }).then(res => console.log('res: ', res));

    window.gtag('config', this.trackerId, { page_path: url });
  }
}
